package dev.pedro.learning.ecommerce.notification.api;import dev.pedro.learning.ecommerce.notification.domain.NotificationRepository;import jakarta.ws.rs.*;import jakarta.ws.rs.core.MediaType;import java.util.UUID;@Path("/notifications")@Produces(MediaType.APPLICATION_JSON)public class NotificationResource{private final NotificationRepository notifications;public NotificationResource(NotificationRepository notifications){this.notifications=notifications;}@GET @Path("/order/{orderId}")public NotificationResponse byOrder(@PathParam("orderId")UUID orderId){var n=notifications.findByOrderId(orderId);if(n==null)throw new NotFoundException();return NotificationResponse.from(n);}}